def transform(grid):
    height = len(grid)
    width = len(grid[0]) if height else 0
    if not height or not width:
        return [row[:] for row in grid]

    # Full-width monochrome rows are samples of a repeating horizontal-stripe
    # sequence; otherwise the clues are parallel rising diagonals (c-r).
    row_samples = {}
    for r, row in enumerate(grid):
        colors = set(row)
        if len(colors) == 1 and row[0] != 0:
            row_samples[r] = row[0]

    if row_samples:
        period, residues = _smallest_period(row_samples)
        return [[residues[r % period] for _ in range(width)] for r in range(height)]

    diagonal_samples = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                position = c - r
                if position in diagonal_samples and diagonal_samples[position] != color:
                    raise ValueError("Conflicting colors on one diagonal")
                diagonal_samples[position] = color

    if not diagonal_samples:
        return [row[:] for row in grid]
    period, residues = _smallest_period(diagonal_samples)
    return [[residues[(c - r) % period] for c in range(width)] for r in range(height)]
